import{_ as d,o as e,c as a,a3 as r}from"./chunks/framework.Ca4XN3PV.js";const p=JSON.parse('{"title":"Qwen3.5 在 4090 上的在线表现","description":"","frontmatter":{},"headers":[],"relativePath":"LLM推理/Qwen3.5-4090性能.md","filePath":"LLM推理/Qwen3.5-4090性能.md","lastUpdated":null}'),o={name:"LLM推理/Qwen3.5-4090性能.md"};function n(h,t,c,l,i,s){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="qwen3-5-在-4090-上的在线表现" tabindex="-1">Qwen3.5 在 4090 上的在线表现 <a class="header-anchor" href="#qwen3-5-在-4090-上的在线表现" aria-label="Permalink to &quot;Qwen3.5 在 4090 上的在线表现&quot;">​</a></h1><blockquote><p>一套已经在跑的文本服务，不是把显卡打满的压测。机器是一张 RTX 4090（显存约 46 GB），vLLM 0.17.1，权重是 Qwen3.5-35B-A3B 的 GPTQ Int4，对外服务名是 Qwen3.5。</p></blockquote><h2 id="启动配置" tabindex="-1">启动配置 <a class="header-anchor" href="#启动配置" aria-label="Permalink to &quot;启动配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>上下文上限</td><td>16384</td></tr><tr><td>显存占用比例</td><td>0.6</td></tr><tr><td>前缀缓存</td><td>打开</td></tr><tr><td>专家并行</td><td>关闭（单卡）</td></tr><tr><td>视觉权重</td><td>不加载</td></tr><tr><td>推理解析</td><td>Qwen3</td></tr><tr><td>工具调用解析</td><td>Qwen3 coder</td></tr></tbody></table><p>调用经过一层转发：转发把 <code>Qwen3.5</code> 和旧的模型别名收成同一个服务名，并在请求里写上 <code>top_k</code> 为 20、关闭 thinking。这些字段有一部分放在 <code>extra_body</code> 里——vLLM 0.17.1 会忽略 <code>extra_body</code>，日志里反复出现该字段被丢弃的警告。<strong>关闭 thinking 要以这一版直接认识的字段生效。</strong></p><p>保留下来的日志从服务跑起来之后才开始，没有引擎启动时的 KV 块总数。下面的数来自在线请求，时间集中在 2026-10-07 到 2026-10-12。</p><h2 id="日志里能确定的事" tabindex="-1">日志里能确定的事 <a class="header-anchor" href="#日志里能确定的事" aria-label="Permalink to &quot;日志里能确定的事&quot;">​</a></h2><p>引擎约每 10 秒打一行，生成吞吐那一列把空闲算进了这 10 秒，不能当成单次 decode 速度。</p><table tabindex="0"><thead><tr><th>指标</th><th>观察值</th><th>解读</th></tr></thead><tbody><tr><td>前缀命中率</td><td>10 月 7 日前后约 39%，之后缓慢升到约 40.5%；10 月 12 日全天稳定在约 41.6%–41.7%</td><td>累计口径，整天几乎不动：新请求只在公共前缀上命中，用户原文和生成结果不断把分母加长</td></tr><tr><td>KV 占用</td><td>多数时候 0，偶尔约 2%（1.5%–1.9%）</td><td>占用回到 0 表示块随请求结束释放；偶发占用出现在「正在跑请求数是 1」的几行。并发很低，四成命中来自跨请求的公共前缀，不是长对话占满显存</td></tr><tr><td>提示侧吞吐</td><td>有请求落在窗口时，平均常约 245 token/s，高时约 260，也有窗口只有每秒几十</td><td>请求在窗口末尾才进来会被拉低；这只是 10 秒窗口平均</td></tr><tr><td>生成侧吞吐</td><td>经常只有 2–5 token/s，空闲窗口为 0</td><td>空闲算进分母的结果；单次请求的 decode 速度这行给不出来，需对单次请求从开始生成到结束生成单独计时</td></tr></tbody></table>',9)])])}const b=d(o,[["render",n]]);export{p as __pageData,b as default};
